<?php
namespace App\Services\Sifi;use App\Models\{User,SifiMonitoringObject};use Illuminate\Support\Facades\{DB,Gate};use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
final class ResearchSessionWorkspace {public function create(User $u,SifiMonitoringObject $o,array $v):string{return DB::transaction(function()use($u,$o,$v){$o=SifiMonitoringObject::whereKey($o->id)->lockForUpdate()->firstOrFail();Gate::forUser($u)->authorize('update',$o);if($o->revision!==(int)$v['object_revision'])throw ValidationException::withMessages(['object_revision'=>'Objek berubah. Muat ulang sebelum membuat rencana.']);if($o->state!=='CONFIGURED')throw ValidationException::withMessages(['object_revision'=>'Objek harus CONFIGURED.']);if(DB::table('sifi_research_sessions')->where('user_id',$u->id)->count()>=100)throw ValidationException::withMessages(['question'=>'Batas 100 sesi akun tercapai.']);$parent=null;if(!empty($v['parent_session_id'])){$parent=DB::table('sifi_research_sessions')->where('id',$v['parent_session_id'])->where('user_id',$u->id)->where('object_id',$o->id)->first();abort_unless($parent,404);if(now()->gte($parent->expires_at))throw ValidationException::withMessages(['parent_session_id'=>'Sesi kedaluwarsa. Mulai sesi baru.']);}$limits=['query_limit'=>(int)$v['query_limit'],'result_limit'=>(int)$v['result_limit'],'request_limit'=>0,'byte_limit'=>0,'time_limit_ms'=>1000,'cost_limit'=>0,'language'=>$v['language']??null,'source_type'=>$v['source_type']??null,'time_window'=>$v['time_window']??'UNSPECIFIED'];$planner=app(DeterministicResearchPlanner::class);$plan=$planner->plan($o,$v['question'],$limits);$results=$planner->execute($o,$plan);$reason=$results['stopping_reason'];$id=(string)Str::uuid();$now=now();DB::table('sifi_research_sessions')->insert(['id'=>$id,'user_id'=>$u->id,'object_id'=>$o->id,'parent_id'=>$parent?->id,'revision'=>1,'object_revision'=>$o->revision,'question'=>$v['question'],'plan_json'=>json_encode($plan,JSON_THROW_ON_ERROR),'results_json'=>json_encode($results,JSON_THROW_ON_ERROR),'stopping_reason'=>$reason,'expires_at'=>$now->copy()->addDays(30),'created_at'=>$now,'updated_at'=>$now]);DB::table('sifi_research_session_audit')->insert(['session_id'=>$id,'actor_user_id'=>$u->id,'action'=>$parent?'FOLLOW_UP_PLANNED':'DRAFT_PLANNED','snapshot_json'=>json_encode(['object_revision'=>$o->revision,'question_sha256'=>hash('sha256',$v['question']),'plan_sha256'=>hash('sha256',json_encode($plan)),'provider'=>'LOCAL_SYNTHETIC_CATALOG','network'=>'OFF','ai'=>'OFF','stopping_reason'=>$reason],JSON_THROW_ON_ERROR),'created_at'=>$now]);return $id;});}public function history(User $u,SifiMonitoringObject $o):array {Gate::forUser($u)->authorize('view',$o);return DB::table('sifi_research_sessions')->where('user_id',$u->id)->where('object_id',$o->id)->orderByDesc('created_at')->limit(30)->get()->map(fn($s)=>['id'=>$s->id,'parent_id'=>$s->parent_id,'revision'=>(int)$s->revision,'object_revision'=>(int)$s->object_revision,'question'=>now()->gte($s->expires_at)?null:$s->question,'plan'=>now()->gte($s->expires_at)?null:json_decode($s->plan_json,true,32,JSON_THROW_ON_ERROR),'results'=>now()->gte($s->expires_at)?null:json_decode($s->results_json,true,32,JSON_THROW_ON_ERROR),'stopping_reason'=>$s->stopping_reason,'expires_at'=>$s->expires_at,'expired'=>now()->gte($s->expires_at),'created_at'=>$s->created_at])->all();}}
